// Vis weather map: live satellite imagery loops (NASA GIBS and EUMETSAT EUMETView tiles), radar (NOAA MRMS, ECCC),
// lightning, the GFS jet stream as moving streaks, snow depth, smoke, hail reports, and Vis's forecast points.
// Hand-written (not generated by tools/build_site.py). Leaflet loads only when the map nears the viewport, and a
// loop's frames load only when Play is pressed; the page shows the newest frame by default.
// Layer names, time steps and delays come from data/wxmap.json (tools/wxmap.py); winds and snow from
// data/wind250.json and data/snow.json (tools/gfs.py); hail and smoke from data/hail.json and data/smoke.json
// (tools/wxobs.py). Each is written by the build, and a missing file only hides its layer.

const T = window.TicTime;
const FRAMES = { default: 12, precip: 6 };        // 2 hours of 10-minute imagery; 3 hours of 30-minute IMERG
const FRAME_MS = 550;
const HOLD_MS = 1600;                             // pause on the newest frame before the loop restarts
const COLOURS = { green: "#3E9B4F", yellow: "#E8C547", amber: "#F08C2E", red: "#D64545" };
const KT = 1.94384;                               // knots per m/s

const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const isoZ = (ms) => new Date(ms).toISOString().slice(0, 19) + "Z";
const fmt = (ms) => (T ? T.format(isoZ(ms)) : isoZ(ms).replace("T", " ").slice(0, 16) + " UTC");
const reducedMotion = () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

function loadLeaflet() {
  if (window.L) return Promise.resolve(window.L);
  return new Promise((ok, fail) => {
    const s = document.createElement("script");
    s.src = "vendor/leaflet/leaflet.js";
    s.onload = () => ok(window.L);
    s.onerror = fail;
    document.head.appendChild(s);
  });
}

async function getJSON(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.json();
}
const maybeJSON = (url) => getJSON(url).then((d) => (d && d.ok ? d : null)).catch(() => null);

// The newest frame each layer should have by now (its delay at the last build, plus one step of margin), and a
// shared timeline at the coarsest step among the layers shown.
function timeline(layers, count, now = Date.now()) {
  const step = Math.max(...layers.map((l) => l.step_s)) * 1000;
  const newest = Math.min(...layers.map((l) => {
    const s = l.step_s * 1000;
    return Math.floor((now - l.lag_s * 1000) / s) * s - s;
  }));
  const end = Math.floor(newest / step) * step;
  return Array.from({ length: count }, (_, i) => end - (count - 1 - i) * step);
}

const layerTime = (l, t) => {
  const s = l.step_s * 1000;
  const iso = isoZ(Math.floor(t / s) * s);
  return l.step_s >= 86400 ? iso.slice(0, 10) : iso;   // daily layers take a date
};

function tileLayer(L, l, t, pane, z) {
  const bounds = L.latLngBounds([l.south ?? -85, l.west], [l.north ?? 85, l.east]);
  const common = { pane, opacity: 0, bounds, noWrap: true, zIndex: z, maxZoom: 8, keepBuffer: 0, updateWhenIdle: true };
  if (l.source === "gibs") {
    return L.tileLayer(l.url.replace("{time}", layerTime(l, t)), { ...common, maxNativeZoom: l.max_zoom });
  }
  return L.tileLayer.wms(l.wms, { ...common, layers: l.layer, format: "image/png", transparent: true,
    version: "1.3.0", time: layerTime(l, t), tileSize: 512 });
}

// A canvas the size of the map, above the imagery, redrawn in screen space after each pan or zoom.
class ScreenCanvas {
  constructor(L, map, z) {
    this.map = map;
    const c = (this.canvas = L.DomUtil.create("canvas", "wx-canvas"));
    c.style.zIndex = String(z);
    c.hidden = true;
    map.getContainer().appendChild(c);
    this.ctx = c.getContext("2d");
  }
  fit() {
    const s = this.map.getSize();
    const r = window.devicePixelRatio || 1;
    this.w = s.x; this.h = s.y;
    this.canvas.width = Math.round(s.x * r); this.canvas.height = Math.round(s.y * r);
    this.canvas.style.width = `${s.x}px`; this.canvas.style.height = `${s.y}px`;
    this.ctx.setTransform(r, 0, 0, r, 0, 0);
  }
  clear() { this.ctx.clearRect(0, 0, this.w || 0, this.h || 0); }
}

// Bilinear sample of a north-to-south, west-to-east global grid (lon0 in 0..360, dlat negative).
function sampler(g, fields) {
  return (lat, lon) => {
    const x = ((((lon - g.lon0) % 360) + 360) % 360) / g.dlon;
    const y = (lat - g.lat0) / g.dlat;
    if (!(y >= 0 && y <= g.ny - 1)) return null;
    const x0 = Math.floor(x) % g.nx, x1 = (x0 + 1) % g.nx, y0 = Math.floor(y), y1 = Math.min(y0 + 1, g.ny - 1);
    const fx = x - Math.floor(x), fy = y - y0;
    return fields.map((a) => (a[y0 * g.nx + x0] * (1 - fx) + a[y0 * g.nx + x1] * fx) * (1 - fy)
      + (a[y1 * g.nx + x0] * (1 - fx) + a[y1 * g.nx + x1] * fx) * fy);
  };
}

// GFS 250 hPa wind as streaks that drift with the wind, coloured by speed; the jet stream shows yellow and up.
const WIND_BINS = [   // [from knots, colour]
  [0, "rgba(233,238,244,0.30)"], [30, "rgba(140,200,255,0.70)"], [60, "#F2D24B"], [90, "#F08C2E"], [120, "#E8457E"],
];
class WindLayer {
  constructor(L, map, w) {
    this.map = map; this.w = w;
    this.cv = new ScreenCanvas(L, map, 450);
    this.sample = sampler(w, [w.u, w.v]);
    this.on = false; this.raf = null; this.parts = [];
    const pause = () => { this.stopLoop(); this.cv.clear(); };
    const resume = () => { if (this.on) this.start(); };
    map.on("movestart zoomstart", pause);
    map.on("moveend zoomend resize", resume);
  }
  bin(ms) { const kt = ms * KT; let i = 0; while (i + 1 < WIND_BINS.length && kt >= WIND_BINS[i + 1][0]) i++; return i; }
  seed(p) { p.x = Math.random() * this.cv.w; p.y = Math.random() * this.cv.h; p.age = Math.floor(Math.random() * 80); }
  show(on) {
    this.on = on;
    this.cv.canvas.hidden = !on;
    if (on) this.start(); else { this.stopLoop(); this.cv.clear(); }
  }
  start() {
    this.stopLoop();
    this.cv.fit();
    const n = Math.min(3000, Math.round((this.cv.w * this.cv.h) / 300));
    this.parts = Array.from({ length: n }, () => { const p = {}; this.seed(p); return p; });
    if (reducedMotion()) { for (let i = 0; i < 30; i++) this.step(false); return; }
    const loop = () => { this.step(true); this.raf = requestAnimationFrame(loop); };
    this.raf = requestAnimationFrame(loop);
  }
  stopLoop() { if (this.raf) cancelAnimationFrame(this.raf); this.raf = null; }
  step(fade) {
    const { ctx, w, h } = this.cv;
    if (fade) {
      ctx.globalCompositeOperation = "destination-in";
      ctx.fillStyle = "rgba(0,0,0,0.92)";
      ctx.fillRect(0, 0, w, h);
      ctx.globalCompositeOperation = "source-over";
    }
    const segs = WIND_BINS.map(() => []);
    const k = 0.07;                                // pixels per frame per m/s, at any zoom
    for (const p of this.parts) {
      if (p.age++ > 90) { this.seed(p); p.age = 0; continue; }
      const ll = this.map.containerPointToLatLng([p.x, p.y]);
      const uv = this.sample(ll.lat, ll.lng);
      if (!uv) { this.seed(p); continue; }
      const nx = p.x + uv[0] * k, ny = p.y - uv[1] * k;
      segs[this.bin(Math.hypot(uv[0], uv[1]))].push(p.x, p.y, nx, ny);
      p.x = nx; p.y = ny;
      if (nx < 0 || ny < 0 || nx > w || ny > h) this.seed(p);
    }
    ctx.lineWidth = 1.3;
    segs.forEach((s, i) => {
      if (!s.length) return;
      ctx.strokeStyle = WIND_BINS[i][1];
      ctx.beginPath();
      for (let j = 0; j < s.length; j += 4) { ctx.moveTo(s[j], s[j + 1]); ctx.lineTo(s[j + 2], s[j + 3]); }
      ctx.stroke();
    });
  }
}

// GFS snow depth as shaded 1-degree cells: runs of cells in the same band along a row are joined, and each band is
// one multi-ring polygon in the overlay pane (above the imagery, below lightning and the outlines).
const SNOW_BINS = [[1, "#DCEBFA", 0.5], [5, "#A9CDF2", 0.6], [15, "#6FA8E6", 0.65], [30, "#3D7DD8", 0.7],
  [60, "#6A4FC9", 0.75], [120, "#B03FB5", 0.8]];
const snowBin = (cm) => { let b = -1; while (b + 1 < SNOW_BINS.length && cm >= SNOW_BINS[b + 1][0]) b++; return b; };
function snowRings(s) {
  const rings = SNOW_BINS.map(() => []);
  const wrap = (lon) => ((((lon + 180) % 360) + 360) % 360) - 180;
  for (let j = 0; j < s.ny; j++) {
    const lat = s.lat0 + j * s.dlat;
    const n = lat - s.dlat / 2, so = lat + s.dlat / 2;
    if (so > 85 || n < -85) continue;
    let i = 0;
    while (i < s.nx) {
      const b = snowBin(s.cm[j * s.nx + i]);
      let k = i + 1;
      while (k < s.nx && snowBin(s.cm[j * s.nx + k]) === b && wrap(s.lon0 + k * s.dlon) > wrap(s.lon0 + i * s.dlon)) k++;
      if (b >= 0) {
        const w = wrap(s.lon0 + i * s.dlon) - s.dlon / 2, e = wrap(s.lon0 + (k - 1) * s.dlon) + s.dlon / 2;
        rings[b].push([[n, w], [n, e], [so, e], [so, w]]);
      }
      i = k;
    }
  }
  return rings;
}
class SnowLayer {
  constructor(L, map, s) {
    this.map = map;
    this.g = L.layerGroup();
    const r = L.canvas({ pane: "wx-over" });
    snowRings(s).forEach((rings, b) => {
      if (rings.length) L.polygon(rings.map((x) => [x]), { pane: "wx-over", renderer: r, stroke: false, fillColor: SNOW_BINS[b][1], fillOpacity: SNOW_BINS[b][2], interactive: false }).addTo(this.g);
    });
  }
  show(on) { on ? this.g.addTo(this.map) : this.map.removeLayer(this.g); }
}

const SMOKE = { Light: ["#C9B79C", 0.3], Medium: ["#9C8466", 0.42], Heavy: ["#5E4A36", 0.55] };

class WxMap {
  constructor(L, manifest, forecast, outlines, extra) {
    this.L = L;
    this.m = manifest;
    this.frames = [];          // { t, layers: [tileLayer], loaded: Promise }
    this.idx = 0;
    this.timer = null;
    this.product = (manifest.products || []).find((p) => p.group === "imagery") || null;
    this.overlays = (manifest.products || []).filter((p) => p.group === "overlay");
    this.shown = new Set();    // ids of tile overlays switched on

    const map = (this.map = L.map("wx-map", { preferCanvas: true, minZoom: 1, maxZoom: 8, worldCopyJump: false, zoomSnap: 0.5,
      maxBounds: [[-85, -220], [85, 220]], maxBoundsViscosity: 0.8, attributionControl: true, zoomControl: true }));
    map.setView([28, 35], 2);
    map.attributionControl.setPrefix(false);
    for (const [name, z] of [["wx-land", 150], ["wx-img", 250], ["wx-over", 300], ["wx-lightning", 350], ["wx-lines", 420]]) {
      map.createPane(name).style.zIndex = z;
      if (name !== "wx-img") map.getPane(name).style.pointerEvents = "none";
    }
    this.drawOutlines(outlines);
    this.drawPoints(forecast);
    const credits = [...(manifest.credits || [])];
    this.data = {};            // id -> { name, note, show(on) } for the layers drawn from the build's own files
    if (extra.wind) { this.addData("wind", "Jet stream", windNote(extra.wind), new WindLayer(L, map, extra.wind)); credits.push(...extra.wind.credits); }
    if (extra.snow) { this.addData("snow", "Snow depth", snowNote(extra.snow), new SnowLayer(L, map, extra.snow)); credits.push(...extra.snow.credits); }
    if (extra.smoke) { this.addData("smoke", "Smoke (N. America)", smokeNote(extra.smoke), this.smokeLayer(extra.smoke)); credits.push(...extra.smoke.credits); }
    if (extra.hail) { this.addData("hail", "Hail reports (US)", hailNote(extra.hail), this.hailLayer(extra.hail)); credits.push(...extra.hail.credits); }
    const seen = new Set();
    for (const c of credits) {
      if (seen.has(c.text)) continue;
      seen.add(c.text);
      map.attributionControl.addAttribution(`<a href="${esc(c.url)}" rel="noopener">${esc(c.text)}</a>`);
    }
    map.attributionControl.addAttribution("Outlines: Natural Earth");
    new ResizeObserver(() => map.invalidateSize()).observe($("wx-map"));
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible" && !this.timer && Date.now() - this.builtAt > 10 * 60 * 1000) this.reset();
    });
  }

  addData(id, name, note, layer) { this.data[id] = { id, name, note, layer }; }

  smokeLayer(sm) {
    const L = this.L;
    const g = L.layerGroup();
    const r = L.canvas({ pane: "wx-over" });
    for (const d of ["Light", "Medium", "Heavy"]) {
      const rings = sm.polygons.filter((p) => p.density === d).map((p) => p.ring.map(([x, y]) => [y, x]));
      if (rings.length) L.polygon(rings.map((x) => [x]), { pane: "wx-over", renderer: r, stroke: false, fillColor: SMOKE[d][0], fillOpacity: SMOKE[d][1], interactive: false }).addTo(g);
    }
    return { show: (on) => (on ? g.addTo(this.map) : this.map.removeLayer(g)) };
  }

  hailLayer(h) {
    const L = this.L;
    const g = L.layerGroup();
    for (const r of h.reports) {
      const big = r.in >= 2;
      L.circleMarker([r.lat, r.lon], { radius: 3 + Math.min(r.in, 4) * 1.6, weight: 1, color: "#0B1A2B", fillColor: big ? "#D64545" : "#7FD3F7", fillOpacity: 0.9 })
        .bindPopup(`<b>Hail ${esc(r.in.toFixed(2))} in</b><br>${esc(r.place)}<br>${esc(fmt(Date.parse(r.time)))}<br><span class="small">Preliminary SPC report</span>`)
        .addTo(g);
    }
    return { show: (on) => (on ? g.addTo(this.map) : this.map.removeLayer(g)) };
  }

  drawOutlines(o) {
    if (!o) return;
    const L = this.L;
    const flip = (ln) => ln.map(([x, y]) => [y, x]);
    L.polygon(o.land.map((r) => [flip(r)]), { pane: "wx-land", renderer: L.canvas({ pane: "wx-land" }), stroke: false,
      fillColor: "#24344A", fillOpacity: 1, interactive: false }).addTo(this.map);
    const lines = L.canvas({ pane: "wx-lines" });
    L.polyline(o.land.map(flip), { pane: "wx-lines", renderer: lines, color: "#E9EEF4", weight: 0.8, opacity: 0.75, interactive: false }).addTo(this.map);
    L.polyline(o.borders.map(flip), { pane: "wx-lines", renderer: lines, color: "#E9EEF4", weight: 0.6, opacity: 0.5, dashArray: "3 3", interactive: false }).addTo(this.map);
  }

  drawPoints(fc) {
    const L = this.L;
    this.points = L.layerGroup();
    for (const z of fc?.zones || []) {
      const colour = z.days?.[0]?.colour || "green";
      const alt = z.role === "alternate";
      L.circleMarker([z.lat, z.lon], { radius: alt ? 4 : 6, weight: 1.5, color: "#0B1A2B", fillColor: COLOURS[colour] || "#999", fillOpacity: 0.95 })
        .bindPopup(`<b>${esc(z.name)}</b>${alt ? " (alternate)" : ""}<br>${esc(z.station)} · <span class="mono">${esc(z.icao)}</span><br>Today: <b>${esc(colour.toUpperCase())}</b><br><a href="#zone-${esc(z.id)}">See the row</a>`)
        .addTo(this.points);
    }
    this.points.addTo(this.map);
  }

  activeOverlays() { return this.overlays.filter((o) => this.shown.has(o.id)); }

  layersAt(t) {
    const L = this.L;
    const out = [];
    (this.product?.layers || []).forEach((l, i) => out.push(tileLayer(L, l, t, "wx-img", 10 + i)));
    const ot = this.overlayT ?? t;
    this.activeOverlays().forEach((o, k) => o.layers.forEach((l, i) =>
      out.push(tileLayer(L, l, ot, o.id === "lightning" ? "wx-lightning" : "wx-over", 20 + k * 10 + i))));
    return out;
  }

  addFrame(t) {
    const layers = this.layersAt(t);
    const loaded = Promise.all(layers.map((ly) => new Promise((ok) => { ly.once("load", ok); setTimeout(ok, 10000); })));
    layers.forEach((ly) => ly.addTo(this.map));
    return { t, layers, loaded };
  }

  show(i) {
    this.idx = i;
    this.frames.forEach((f, j) => f.layers.forEach((ly) => ly.setOpacity(j === i ? (ly.options.pane === "wx-img" ? 0.92 : 1) : 0)));
    const f = this.frames[i];
    $("wx-time").textContent = f ? `${fmt(f.t)}${i === this.frames.length - 1 ? " · newest" : ""}` : "–";
    $("wx-frame").value = String(i);
  }

  clear() {
    this.stop();
    this.frames.forEach((f) => f.layers.forEach((ly) => this.map.removeLayer(ly)));
    this.frames = [];
  }

  // Newest frame only: the light default. The timeline spans the imagery and every tile overlay switched on, so
  // all of them show the same moment; under once-a-day imagery the overlays keep their own newest frame.
  reset() {
    this.clear();
    this.builtAt = Date.now();
    const p = this.product;
    const over = this.activeOverlays().flatMap((o) => o.layers);
    const daily = p && Math.max(...p.layers.map((l) => l.step_s)) >= 86400;
    this.overlayT = daily && over.length ? timeline(over, 1)[0] : null;
    const timed = daily ? p.layers : [...(p?.layers || []), ...over];
    if (!timed.length) { $("wx-time").textContent = "Imagery unavailable"; return; }
    const count = p ? (p.frames || FRAMES[p.id] || FRAMES.default) : FRAMES.default;
    const times = timeline(timed, count);
    this.times = times;
    this.frames = [this.addFrame(times[times.length - 1])];
    const slider = $("wx-frame");
    slider.max = "0"; slider.disabled = true;
    this.show(0);
    $("wx-note").textContent = p ? p.note : "";
    $("wx-play").textContent = "Play loop";
    $("wx-play").disabled = times.length < 2;
  }

  async play() {
    if (this.timer) { this.stop(); return; }
    if (this.frames.length < this.times.length) {
      const newest = this.frames.pop();
      this.frames = this.times.slice(0, -1).map((t) => this.addFrame(t)).concat([newest]);
      const slider = $("wx-frame");
      slider.max = String(this.frames.length - 1); slider.disabled = false;
      this.show(this.frames.length - 1);
      let n = 0;
      $("wx-play").textContent = `Loading 0/${this.frames.length}`;
      await Promise.all(this.frames.map((f) => f.loaded.then(() => { $("wx-play").textContent = `Loading ${++n}/${this.frames.length}`; })));
    }
    $("wx-play").textContent = "Pause";
    const tick = () => {
      const next = (this.idx + 1) % this.frames.length;
      this.show(next);
      this.timer = setTimeout(tick, next === this.frames.length - 1 ? HOLD_MS : FRAME_MS);
    };
    this.show(0);
    this.timer = setTimeout(tick, FRAME_MS);
  }

  stop() {
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    if (this.frames.length) $("wx-play").textContent = "Play loop";
  }
}

const hhmm = (iso) => fmt(Date.parse(iso));
function windNote(w) { return `NOAA GFS winds at 250 hPa (about 34,000 ft), run ${hhmm(w.run)}, valid ${hhmm(w.valid)}. Streaks show the jet stream yellow from 60 kt, orange from 90 kt, pink from 120 kt.`; }
function snowNote(s) { return `Snow on the ground from the NOAA GFS model (1° grid), valid ${hhmm(s.valid)}: pale under 5 cm, blue to 60 cm, purple deeper. A model estimate, not measured snowfall.`; }
function smokeNote(s) { return `NOAA smoke analysis for ${s.date} over North America (light, medium and heavy), drawn by analysts from satellite images during the day.`; }
function hailNote(h) { return `NOAA Storm Prediction Center preliminary hail reports since ${hhmm(h.since)}: ${h.reports.length} so far. Red is 2 inches or larger. US only.`; }

function controls(wx) {
  const box = $("wx-products");
  const imagery = (wx.m.products || []).filter((p) => p.group === "imagery");
  box.innerHTML = imagery.map((p) => `<button type="button" class="wx-btn" data-id="${esc(p.id)}" aria-pressed="${p === wx.product}" title="${esc(p.layers.map((l) => l.sector_name).join(", "))}">${esc(p.name)}</button>`).join("");
  box.addEventListener("click", (e) => {
    const b = e.target.closest("button[data-id]");
    if (!b) return;
    wx.product = imagery.find((p) => p.id === b.dataset.id);
    box.querySelectorAll("button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
    wx.reset();
  });

  const ov = $("wx-overlays");
  const items = [
    ...wx.overlays.map((o) => ({ id: o.id, name: o.name, note: o.note, kind: "tiles" })),
    ...Object.values(wx.data).map((d) => ({ id: d.id, name: d.name, note: d.note, kind: "data" })),
  ];
  ov.innerHTML = items.map((it) => `<label class="wx-check" title="${esc(it.note)}"><input type="checkbox" data-id="${esc(it.id)}" data-kind="${it.kind}"> ${esc(it.name)}</label>`).join("")
    + `<label class="wx-check"><input type="checkbox" id="wx-points" checked> Forecast points</label>`;
  const notes = $("wx-overlay-notes");
  const showNotes = () => {
    const on = items.filter((it) => ov.querySelector(`input[data-id="${it.id}"]`)?.checked);
    notes.innerHTML = on.map((it) => `<li><b>${esc(it.name)}:</b> ${esc(it.note)}</li>`).join("");
    notes.hidden = !on.length;
  };
  ov.addEventListener("change", (e) => {
    const c = e.target;
    if (c.id === "wx-points") { c.checked ? wx.points.addTo(wx.map) : wx.map.removeLayer(wx.points); return; }
    const id = c.dataset.id;
    if (c.dataset.kind === "data") wx.data[id].layer.show(c.checked);
    else { c.checked ? wx.shown.add(id) : wx.shown.delete(id); wx.reset(); }
    showNotes();
  });
  $("wx-play").addEventListener("click", () => wx.play());
  $("wx-frame").addEventListener("input", (e) => { wx.stop(); wx.show(Number(e.target.value)); });
  if (!wx.product) $("wx-play").disabled = true;
}

async function start() {
  const status = $("wx-status");
  try {
    const [L, manifest, forecast, outlines, wind, snow, smoke, hail] = await Promise.all([
      loadLeaflet(),
      getJSON("data/wxmap.json").catch(() => ({ ok: false, products: [] })),
      getJSON("data/forecast.json").catch(() => null),
      getJSON("geo/outlines.json").catch(() => null),
      maybeJSON("data/wind250.json"), maybeJSON("data/snow.json"), maybeJSON("data/smoke.json"), maybeJSON("data/hail.json"),
    ]);
    const wx = new WxMap(L, manifest, forecast, outlines, { wind, snow, smoke, hail });
    controls(wx);
    wx.reset();
    status.hidden = manifest.ok !== false;
    if (manifest.ok === false) status.textContent = "Satellite imagery is unavailable right now; the forecast points still show.";
    if (T) T.onChange(() => wx.show(wx.idx));
  } catch (e) {
    status.hidden = false;
    status.textContent = "The map could not load.";
  }
}

const el = $("wx-map");
if (el) {
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver((es) => { if (es.some((x) => x.isIntersecting)) { io.disconnect(); start(); } }, { rootMargin: "300px" });
    io.observe(el);
  } else {
    start();
  }
}

export { timeline, sampler, snowRings };
